with enriched as (select id, end_date, status, round(monthly_fee / sum(monthly_fee) over (partition by plan), 4) monthly_fee_share, ntile(5) over (partition by plan order by monthly_fee, id) monthly_fee_bucket, avg(monthly_fee) over (order by end_date, id rows between 2 preceding and 1 preceding) monthly_fee_avg_2_prior, lag(monthly_fee, 1) over (partition by status order by end_date, id) prev_monthly_fee from subscriptions) select id, end_date, monthly_fee_share, monthly_fee_bucket, monthly_fee_avg_2_prior, prev_monthly_fee from enriched order by monthly_fee_bucket desc;
